import sys

def memoized_fibonacci():
    cache = {}
    def fibonacci(n):
        if n in [0, 1]:
            return n
        if n in cache:
            return cache[n]
        cache[n] = fibonacci(n - 1) + fibonacci(n - 2)
        return cache[n]
    return fibonacci

if __name__ == '__main__':
    fib = memoized_fibonacci()
    input_data = sys.stdin.read().strip()
    if input_data:
        n = int(input_data)
        print(fib(n))

