    if not s:
        return

    res = list(s)
    n = len(res)

    for i in range(n):
        if res[i] == '?':
            for candidate in ('a', 'b', 'c'):
                # Check left neighbor
                if i > 0 and res[i - 1] == candidate:
                    continue
                # Check right neighbor
                if i < n - 1 and res[i + 1] == candidate:
