import sys

def solve():
    input = sys.stdin.read
    data = input().split()
    if not data:
        return

    n = int(data[0])
    a = [int(x) for x in data[1:]]

    a.sort()

    def check(k):
        # Check if there exists a window of size k with max - min <= 5
        for i in range(n - k + 1):
            if a[i + k - 1] - a[i] <= 5:
                return True
        return False

    low = 1
    high = n
    ans = 1

    while low <= high:
        mid = (low + high) // 2
        if check(mid):
            ans = mid
            low = mid + 1
        else:
            high = mid - 1

    print(ans)

if __name__ == '__main__':
    solve()
